INSERT INTO item VALUES (60,'Protection +10','Ring','Epic','No',NULL,'20','2,000,000 gp',NULL,NULL,NULL,NULL,'\n      <div topic=\"Protection\" level=\"8\"><p><b>Protection:</b> This ring offers continual magical protection in the form of a deflection bonus to Armor Class of +6 or higher.</p><p><i>Caster Level:</i> 20th: <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>shield of faith</i>,  creator\'s caster level must be three times the ring\'s bonus; <i>Market Price:</i> 720,000 gp (+6), 980,000 gp (+7), 1,280,000 gp (+8), 1,620,000 gp (+9), 2,000,000 gp (+10).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (61,'Epic Wizardry V','Ring','Epic','No',NULL,'23','250,000 gp',NULL,'Forge Ring, Forge Epic Ring, wish',NULL,NULL,'\n      <div topic=\"Epic Wizardry\" level=\"8\"><p><b>Epic Wizardry:</b> Like the <i>ring of wizardry</i>,  this ring comes in a variety of types useful only to arcane spellcasters. The wearer\'s arcane spells per day are doubled for one particular spell level. An <i>epic ring of wizardry V</i> doubles 5th-level spells, an <i>epic ring of wizardry VI</i> doubles 6th-level spells, an <i>epic ring of wizardry VII</i> doubles 7th-level spells, an <i>epic ring of wizardry VIII</i> doubles 8th-level spells, and an <i>epic ring of wizardry IX</i> doubles 9th-level spells. Bonus spells from high ability scores, school specialization, or any other source are not doubled.</p><p><i>Caster Level:</i> 23rd (<i>epic wizardry</i> V), 26th (<i>epic wizardry VI</i>), 29th (<i>epic wizardry VII</i>), 32nd (<i>epic wizardry VIII</i>), 35th (<i>epic wizardry IX</i>); <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>wish; Market Price:</i> 250,000 gp (<i>epic wizardry</i> V), 360,000 gp (<i>epic wizardry VI</i>), 490,000 gp (<i>epic wizardry VII</i>), 640,000 gp (<i>epic wizardry VIII</i>), 810,000 gp (<i>epic wizardry IX</i>).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
INSERT INTO item VALUES (62,'Epic Wizardry VI','Ring','Epic','No',NULL,'23','360,000 gp',NULL,'Forge Ring, Forge Epic Ring, wish',NULL,NULL,'\n      <div topic=\"Epic Wizardry\" level=\"8\"><p><b>Epic Wizardry:</b> Like the <i>ring of wizardry</i>,  this ring comes in a variety of types useful only to arcane spellcasters. The wearer\'s arcane spells per day are doubled for one particular spell level. An <i>epic ring of wizardry V</i> doubles 5th-level spells, an <i>epic ring of wizardry VI</i> doubles 6th-level spells, an <i>epic ring of wizardry VII</i> doubles 7th-level spells, an <i>epic ring of wizardry VIII</i> doubles 8th-level spells, and an <i>epic ring of wizardry IX</i> doubles 9th-level spells. Bonus spells from high ability scores, school specialization, or any other source are not doubled.</p><p><i>Caster Level:</i> 23rd (<i>epic wizardry</i> V), 26th (<i>epic wizardry VI</i>), 29th (<i>epic wizardry VII</i>), 32nd (<i>epic wizardry VIII</i>), 35th (<i>epic wizardry IX</i>); <i>Prerequisites:</i> Forge Ring, Forge Epic Ring, <i>wish; Market Price:</i> 250,000 gp (<i>epic wizardry</i> V), 360,000 gp (<i>epic wizardry VI</i>), 490,000 gp (<i>epic wizardry VII</i>), 640,000 gp (<i>epic wizardry VIII</i>), 810,000 gp (<i>epic wizardry IX</i>).</p>\n</div>\n    ','SRD 3.5 EpicMagicItems1');
