INSERT INTO item VALUES (129,'Bracers of Epic Armor +14','Wondrous','Epic','No',NULL,'20','1,960,000',NULL,'Craft Wondrous Item, Craft Epic Wondrous Item, mage armor, creator\'s caster level must be twice the bracers\' bonus',NULL,'1 lb','\n      <div topic=\"Bracers of Epic Armor\" level=\"8\"><p><b>Bracers of Epic Armor:</b> These items surround the wearer with an invisible but tangible field of force, granting him or her an armor bonus of +11 or higher, just as though he or she were wearing armor. Both bracers must be worn for the magic to be effective.</p><p><i>Caster Level:</i> 20th; <i>Prerequisites:</i> Craft Wondrous Item, Craft Epic Wondrous Item, <i>mage armor</i>,  creator\'s caster level must be twice the bracers\' bonus; <i>Market Price:</i> 1,210,000 (+11), 1,440,000 (+12), 1,690,000 gp (+13), 1,960,000 (+14), 2,250,000 gp (+15); <i>Weight:</i> 1 lb.</p>\n</div>\n    ','SRD 3.5 EpicMagicItems2');
